<script setup lang="ts">import{onMounted,onUnmounted}from'vue';const p=withDefaults(defineProps<{modelValue:boolean,title:string,description?:string,locked?:boolean}>(),{locked:false,description:''});const emit=defineEmits(['update:modelValue']);function close(){if(!p.locked)emit('update:modelValue',false)}function key(e:KeyboardEvent){if(e.key==='Escape')close()}onMounted(()=>document.addEventListener('keydown',key));onUnmounted(()=>document.removeEventListener('keydown',key))</script>
<template><Teleport to="body"><Transition name="modal"><div v-if="modelValue" class="overlay" @mousedown.self="close"><section class="modal" role="dialog" aria-modal="true"><header class="panel-head"><div><h2>{{title}}</h2><p v-if="description">{{description}}</p></div><button v-if="!locked" class="icon-btn" aria-label="关闭" @click="close">×</button></header><div class="panel-body"><slot/></div></section></div></Transition></Teleport></template>
